import json, sys, html as _h

BOOK = {'title': 'Seraphina Moon of Dragonpeak', 'author': 'Signature original', 'genre': 'Dragon Tales', 'chapters': [{'n': 1, 'title': 'The Call', 'text': "the wizard Old Fenwick arrived with a pack, a sword, and no patience for goodbyes. 'You're the one the songs mean,' the wizard Old Fenwick said. 'the Crystal of Dawn chose you. Don't argue with songs.'\n\nThey left Dragonpeak at dusk, the road winding into the unknown. Behind them, lights went out one by one as the dragon Karthax's shadow spread. Ahead: everything.\n\nSeraphina Moon was mending a fence in Dragonpeak when the sky went dark at noon. The elders whispered: the dragon Karthax had taken the Crystal of Dawn, and the old magic was failing. Prophecy or not, someone had to go."}, {'n': 2, 'title': 'Trials of the Road', 'text': "The road through Dragonpeak tested them daily: a bridge held by a troll who demanded riddles, a forest where the trees walked, a river that flowed uphill. the wizard Old Fenwick's wit and Seraphina Moon's courage saw them through each.\n\nThey were ambushed by the dragon Karthax's riders at the enchanted glade. Seraphina Moon fought with a mithril blade borrowed from the wizard Old Fenwick, and learned that bravery is mostly refusing to run at the right moment.\n\nAt the moonwell they met a seer who spoke of the Crystal of Dawn: 'It is not a weapon,' she said, 'though it can kill. It is not a shield, though it can save. It is a promise — and promises are the heaviest magic.'"}, {'n': 3, 'title': 'The Descent', 'text': "the Crystal of Dawn blazed at Seraphina Moon's touch, recognizing its bearer. Power flooded through them — and with it, the terrible knowledge of its price. Every magic, the seer had said, is a promise. This one demanded everything.\n\nAlarms rang. the dragon Karthax's army closed in. the wizard Old Fenwick barred the door with a fallen pillar and grinned. 'Go,' they said. 'I'll hold them.' Seraphina Moon refused to leave — so they held it together, back to back, as the dark came on.\n\nTo reach the Crystal of Dawn, they had to descend into the dragon Karthax's domain: a fortress of black glass where the sun never shone. the wizard Old Fenwick picked the locks; Seraphina Moon carried the light — a single coal of hope in the dark."}, {'n': 4, 'title': 'The Price', 'text': "the wizard Old Fenwick woke and wept to see it. 'The prophecy—' they began. Seraphina Moon said: 'Prophecies are poems, not orders.' But the army of the dragon Karthax was coming, and they had no magic left.\n\nThen the freed prisoners arrived — an army of the grateful, farmers with pitchforks and smiths with hammers, all come to stand with the bearer of the Crystal of Dawn. Seraphina Moon understood at last: the promise was never the crystal. It was this.\n\nThey marched on the dragon Karthax's stronghold with the Crystal of Dawn dark but their hearts lit. Seraphina Moon carried it anyway, empty as it was. Symbols, the wizard Old Fenwick said, have their own magic."}, {'n': 5, 'title': 'The Breaking of the Dark', 'text': "The battle for Dragonpeak raged from dawn to dusk. the dragon Karthax rode out in black armor, terrible and splendid, and challenged Seraphina Moon single combat. The armies held their breath.\n\nthe Crystal of Dawn, dark and cold so long, blazed sudden white — fed not by magic but by the choice. The light struck the dragon Karthax's armor and the armor was empty; the dark lord was only a frightened soul inside, and the soul, seen, fled.\n\nThen Seraphina Moon remembered the seer's words and the dragon's riddle, and did the last thing the dragon Karthax expected: Seraphina Moon offered mercy. 'Yield,' Seraphina Moon said, 'and live.' the dragon Karthax laughed — and in that laugh, the dark wavered."}, {'n': 6, 'title': 'The Return', 'text': "And the choice, the songs say, is always the same: courage lights the dark. In Dragonpeak and everywhere, forever.\n\nThey came home to Dragonpeak in spring, when the orchards bloomed. The songs had already arrived ahead of them, as songs do, and every verse was wrong in the details and right in the heart.\n\nthe wizard Old Fenwick was given the highest honor of Dragonpeak and immediately used it to demand better roads. Seraphina Moon was offered a throne and laughed until they cried. 'I mend fences,' Seraphina Moon said."}]}

def word_count():
    return sum(len(c["text"].split()) for c in BOOK["chapters"])

def print_book(ch=None):
    print("=" * 64)
    print(BOOK["title"].upper(), "\nby", BOOK["author"], "-", BOOK["genre"])
    print("=" * 64)
    for c in BOOK["chapters"]:
        if ch and c["n"] != ch:
            continue
        print("\n\nCHAPTER %d: %s\n%s" % (c["n"], c["title"], "-" * 40))
        print(c["text"])
    print("\n[%d words, %d chapters — complete]" % (word_count(), len(BOOK["chapters"])))

def search(word):
    w = word.lower()
    for c in BOOK["chapters"]:
        for i, para in enumerate(c["text"].split("\n\n")):
            if w in para.lower():
                print("[ch %d, para %d] %s..." % (c["n"], i + 1, para[:160].replace("\n", " ")))

def write_html(path="book.html"):
    parts = ["<html><head><meta charset='utf-8'><title>%s</title></head><body>" % _h.escape(BOOK["title"])]
    parts.append("<h1>%s</h1><p><i>by %s — %s</i></p>" % (_h.escape(BOOK["title"]), _h.escape(BOOK["author"]), _h.escape(BOOK["genre"])))
    for c in BOOK["chapters"]:
        parts.append("<h2>Chapter %d: %s</h2>" % (c["n"], _h.escape(c["title"])))
        for para in c["text"].split("\n\n"):
            parts.append("<p>%s</p>" % _h.escape(para))
    parts.append("</body></html>")
    open(path, "w").write("\n".join(parts))
    print("wrote", path)

if __name__ == "__main__":
    a = sys.argv[1:]
    if a and a[0] == "html":
        write_html()
    elif len(a) >= 2 and a[0] == "search":
        search(a[1])
    elif a and a[0].isdigit():
        print_book(int(a[0]))
    else:
        print_book()

